-- 原库SHOW CREATE VIEW材料，来自既有只读结构核查。仅归档，不执行CREATE、不替换当前来源。
-- 尤其view_warranty保持原36列材料，不自动使用当前31列view_warranty_source。

-- original view: pm_project_header
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `pm_project_header` AS select `pm_project`.`projectId` AS `projectId`,`pm_project`.`projectType` AS `projectType`,`pm_project`.`projectCode` AS `projectCode`,`pm_project`.`projectName` AS `projectName`,`pm_project`.`projectState` AS `projectState`,`pm_project`.`isback` AS `isback`,`pm_project`.`column001` AS `column001`,`pm_project`.`column002` AS `column002`,`pm_project`.`column003` AS `column003`,`pm_project`.`column004` AS `column004`,`pm_project`.`column005` AS `column005`,`pm_project`.`column006` AS `column006`,`pm_project`.`column007` AS `column007`,`pm_project`.`column008` AS `column008`,`pm_project`.`column009` AS `column009`,`pm_project`.`column010` AS `column010`,`pm_project`.`column011` AS `column011`,`pm_project`.`column012` AS `column012`,`pm_project`.`columno12_readonly` AS `columno12_readonly`,`pm_project`.`column013` AS `column013`,`pm_project`.`column014` AS `column014`,`pm_project`.`customerProjectName` AS `customerProjectName`,`pm_project`.`salesType` AS `salesType`,`pm_project`.`majorProjectLevel` AS `majorProjectLevel`,`pm_project`.`compId` AS `compId`,`pm_project`.`createTime` AS `createTime`,`pm_project`.`createBy` AS `createBy`,`pm_project`.`updateTime` AS `updateTime`,`pm_project`.`updateBy` AS `updateBy`,`pm_project`.`effectiveFrom` AS `effectiveFrom`,`pm_project`.`effectiveTo` AS `effectiveTo`,`pm_project`.`disabled` AS `disabled`,`pm_project`.`projectStartTime` AS `projectStartTime`,`pm_project`.`projectRefreshTime` AS `projectRefreshTime`,`pm_project`.`projectCloseTime` AS `projectCloseTime`,`pm_project`.`customInfo` AS `customInfo`,`pm_project`.`customConfig` AS `customConfig` from `pm_project` where (`pm_project`.`projectType` = '10');

-- original view: view_shipment_ems_4_pm
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_shipment_ems_4_pm` AS (select `fc`.`contract_code` AS `contract_code`,`fs`.`receiveName` AS `receiveName`,`fs`.`emsNum` AS `emsNum`,`fs`.`packdate` AS `packdate`,(case when isnull(`fd`.`basicDataName`) then `fs`.`emsCompany` else `fd`.`basicDataName` end) AS `emsCompany`,`fs`.`packlist_id` AS `packId` from ((`fb_contract` `fc` left join `fb_shipment` `fs` on((`fc`.`contract_id` = `fs`.`con_id`))) left join `fnd_basic_data` `fd` on(((`fs`.`emsCompany` = `fd`.`basicDataId`) and (`fd`.`dataTypeCode` = '01')))));

-- original view: view_shipment_info_4_pm
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_shipment_info_4_pm` AS (select `c`.`contract_code` AS `contract_code`,`sb`.`item` AS `itemCode`,`fi`.`itemname` AS `itemModel`,`fi`.`describe_` AS `itemName`,`sb`.`barcode` AS `barcode`,`s`.`packlist_id` AS `packId`,`sb`.`item2` AS `itemCode2`,`fi2`.`itemname` AS `itemModel2`,`fi2`.`describe_` AS `itemName2`,`sb`.`barcode2` AS `barcode2`,`sb`.`profitCenter` AS `profitCenter` from ((((`fb_contract` `c` left join `fb_shipment` `s` on((`c`.`contract_id` = `s`.`con_id`))) left join `fb_shipment_barcode` `sb` on((`s`.`packlist_id` = `sb`.`pack_id`))) left join `fb_items` `fi` on((`sb`.`item` = `fi`.`item`))) left join `fb_items` `fi2` on((`sb`.`item2` = `fi2`.`item`))) where ((`sb`.`barcode` is not null) and (isnull(`sb`.`rma_no`) or (`sb`.`rma_no` = '') or (`sb`.`rma_no` = 'null'))));
